// CountDownLatch: Main thread waits for 3 workers
CountDownLatch latch = new CountDownLatch(3);
// Worker: latch.countDown();

// CyclicBarrier: 3 threads waiting for each other
CyclicBarrier barrier = new CyclicBarrier(3, () -> System.out.println("Phase complete"));
// Worker: barrier.await();
